import openpyxl
wb=openpyxl.load_workbook("documents/compliance-matrix.xlsx")
for ws in wb.worksheets[2:]:
    print("=== SHEET",ws.title)
    rows=list(ws.iter_rows(values_only=True))
    hdr=rows[0]
    for r in rows[1:]:
        if not any(r): continue
        print("---")
        for h,v in zip(hdr,r):
            if v is not None: print(f"[{h}] {v}")
# comments
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if c.comment: print("COMMENT",ws.title,c.coordinate,c.comment.text)
EOF

